#include <stdio.h>

int main(void) {
    int N, M, S;
    scanf("%d", &N);
    scanf("%d", &M);
    scanf("%d", &S);

    for (int i = M; i >= N; i--) {
        int x = i;
        int sum = 0;

        while (x > 0) {
            sum += x % 10;
            x /= 10;
        }

        if (sum == S) {
            printf("%d\n", i);
            return 0;
        }
    }

    printf("-1\n");
    return 0;
}
